/* ==========================================================================
   Malam UI: dark design system for Tailwind v4 + shadcn/ui

   Structure
   1. @theme inline   Tailwind bindings (bg-*, text-*, shadow-*, …)
   2. :root           shared surfaces, text, status (identical in every theme)
   3. themes          accent palettes, selected with data-theme="…" on ANY
                      element (usually <html>). Default = crimson.
   4. derived         gradients/glows recomputed per themed element, so a
                      nested <div data-theme="classic"> re-themes its subtree.

   Dark-first: :root IS the dark theme. `.dark` is kept as an alias so
   shadcn components that use `dark:` variants still resolve.
   ========================================================================== */
@import "tailwindcss";
@import "tw-animate-css";
@import "shadcn/tailwind.css";
@import "@fontsource-variable/figtree";

@custom-variant dark (&:is(.dark *));

@theme inline {
  /* Typography ---------------------------------------------------------- */
  --font-sans: "Figtree Variable", "Motiva Sans", Arial, Helvetica, sans-serif;
  --font-heading: var(--font-sans);
  --font-mono: "JetBrains Mono", Consolas, "SFMono-Regular", Menlo, monospace;

  /* shadcn semantic colors --------------------------------------------- */
  --color-background: var(--background);
  --color-foreground: var(--foreground);
  --color-card: var(--card);
  --color-card-foreground: var(--card-foreground);
  --color-popover: var(--popover);
  --color-popover-foreground: var(--popover-foreground);
  --color-primary: var(--primary);
  --color-primary-foreground: var(--primary-foreground);
  --color-secondary: var(--secondary);
  --color-secondary-foreground: var(--secondary-foreground);
  --color-muted: var(--muted);
  --color-muted-foreground: var(--muted-foreground);
  --color-accent: var(--accent);
  --color-accent-foreground: var(--accent-foreground);
  --color-destructive: var(--destructive);
  --color-border: var(--border);
  --color-input: var(--input);
  --color-ring: var(--ring);
  --color-chart-1: var(--chart-1);
  --color-chart-2: var(--chart-2);
  --color-chart-3: var(--chart-3);
  --color-chart-4: var(--chart-4);
  --color-chart-5: var(--chart-5);
  --color-sidebar: var(--sidebar);
  --color-sidebar-foreground: var(--sidebar-foreground);
  --color-sidebar-primary: var(--sidebar-primary);
  --color-sidebar-primary-foreground: var(--sidebar-primary-foreground);
  --color-sidebar-accent: var(--sidebar-accent);
  --color-sidebar-accent-foreground: var(--sidebar-accent-foreground);
  --color-sidebar-border: var(--sidebar-border);
  --color-sidebar-ring: var(--sidebar-ring);

  /* Malam extensions ----------------------------------------------------- */
  --color-heading: var(--heading);
  --color-header: var(--header);
  --color-surface: var(--surface);
  --color-surface-raised: var(--surface-raised);
  --color-link: var(--link);
  --color-sale: var(--sale);
  --color-sale-foreground: var(--sale-foreground);
  --color-price-surface: var(--price-surface);
  --color-strike: var(--strike);
  --color-cta: var(--cta);
  --color-cta-foreground: var(--cta-foreground);
  --color-review-positive: var(--review-positive);
  --color-review-mixed: var(--review-mixed);
  --color-review-negative: var(--review-negative);
  --color-live: var(--live);

  /* Status colors (theme independent) */
  --color-success: var(--success);
  --color-success-foreground: var(--success-foreground);
  --color-success-text: var(--success-text);
  --color-warning: var(--warning);
  --color-warning-foreground: var(--warning-foreground);
  --color-warning-text: var(--warning-text);
  --color-info: var(--info);
  --color-info-foreground: var(--info-foreground);
  --color-info-text: var(--info-text);
  --color-destructive-foreground: var(--destructive-foreground);
  --color-destructive-text: var(--destructive-text);

  /* Shadows ------------------------------------------------------------- */
  --shadow-glow: var(--glow);
  --shadow-glow-sm: var(--glow-sm);
  --shadow-panel: var(--panel-shadow);

  /* Radius: this design is nearly square. Never exceed radius-lg. ------- */
  --radius-xs: 1px;
  --radius-sm: 2px;
  --radius-md: 3px;
  --radius-lg: var(--radius);
  --radius-xl: var(--radius);
  --radius-2xl: var(--radius);
  --radius-3xl: var(--radius);
  --radius-4xl: 9999px;

  /* Motion ---------------------------------------------------------------*/
  --ease-malam: cubic-bezier(0.25, 0.1, 0.25, 1);
  --animate-capsule-in: capsule-in 0.35s var(--ease-malam) both;

  @keyframes capsule-in {
    from { opacity: 0; transform: translateY(4px); }
    to { opacity: 1; transform: translateY(0); }
  }
}

/* 2. Shared base --------------------------------------------------------- */
:root,
.dark {
  color-scheme: dark;
  --radius: 4px;

  /* Surfaces (darkest → lightest) */
  --header: #0a0a0b;
  --background: #121214;
  --surface: #0d0d0f;
  --card: #19191c;
  --surface-raised: #2a2a30;
  --popover: #232327;
  --muted: #1f1f23;
  --accent: #2a2a30;
  --accent-foreground: #ffffff;

  /* Text */
  --heading: #ffffff;
  --foreground: #d4d4d8;
  --card-foreground: #d4d4d8;
  --popover-foreground: #e4e4e7;
  --muted-foreground: #8e8e96;

  /* Status (theme-independent) */
  --primary-foreground: #ffffff;
  --destructive: #c15755;
  --destructive-foreground: #ffffff;

  /* Status: same in every accent theme. *-text is for tinted backgrounds. */
  --success: #2fbf71;
  --success-foreground: #04210f;
  --success-text: #6ee7a8;
  --warning: #f5a524;
  --warning-foreground: #1f1300;
  --warning-text: #fbbf24;
  --info: #3b9eff;
  --info-foreground: #ffffff;
  --info-text: #7cc4ff;
  --strike: #7b7b83;
  --price-surface: #2f2f35;
  --review-mixed: #b9a074;
  --review-negative: #a34c25;

  /* Lines */
  --destructive-text: color-mix(in srgb, var(--destructive), white 45%);
  --input-border: rgb(0 0 0 / 0.4);
  --inset-shadow: rgb(0 0 0 / 0.4);
  --tint: rgb(0 0 0 / 0.2);
  --panel-shadow: 0 2px 8px rgb(0 0 0 / 0.25);

  --border: rgb(255 255 255 / 0.09);
  --input: #3a3a42;
  --input-placeholder: #8e8e96;

  --chart-3: #7a7a86;
  --chart-5: #b9a074;

  --sidebar: #0a0a0b;
  --sidebar-foreground: #d4d4d8;
  --sidebar-primary-foreground: #ffffff;
  --sidebar-accent: #2a2a30;
  --sidebar-accent-foreground: #ffffff;
  --sidebar-border: rgb(255 255 255 / 0.08);

  --gradient-panel: linear-gradient(180deg, rgb(255 255 255 / 0.045) 0%, rgb(25 25 28 / 0.9) 100%);
  --gradient-hero-info: linear-gradient(135deg, #131316 0%, #222228 100%);
  --gradient-promo: linear-gradient(90deg, #26262c 0%, #1d1d22 100%);
  --page-glow: radial-gradient(ellipse 80% 420px at 50% 0%, rgb(255 255 255 / 0.05), transparent 70%);
}

/* 3. Themes -------------------------------------------------------------- */
/* Every theme defines the same set of variables:
   primary(+from/to) · link · ring · secondary(+fg, hover from/to) · nav-tint
   cta(+fg, from/to) · sale(+fg) · review-positive · live · chart-1/2/4 */

/* Crimson (default): blue · black · red */
:root,
[data-theme="crimson"] {
  --primary: #1a9fff;
  --primary-from: #06bfff;
  --primary-to: #2d73ff;
  --link: #66c0f4;
  --ring: #66c0f4;
  --secondary: rgb(103 193 245 / 0.2);
  --secondary-foreground: #66c0f4;
  --secondary-from: #417a9b;
  --secondary-to: #66c0f4;
  --nav-tint: 62 103 150;

  --cta: #c8232c;
  --cta-from: #e5343d;
  --cta-to: #a3161e;
  --cta-foreground: #ffe3e4;
  --sale: #7a1d24;
  --sale-foreground: #ff6b70;
  --review-positive: #66c0f4;
  --live: #ff3b42;

  --chart-1: #1a9fff;
  --chart-2: #66c0f4;
  --chart-4: #ff4d55;
}

/* Classic: blue · black · green (the original extraction) */
[data-theme="classic"] {
  --primary: #1a9fff;
  --primary-from: #06bfff;
  --primary-to: #2d73ff;
  --link: #66c0f4;
  --ring: #66c0f4;
  --secondary: rgb(103 193 245 / 0.2);
  --secondary-foreground: #66c0f4;
  --secondary-from: #417a9b;
  --secondary-to: #66c0f4;
  --nav-tint: 62 103 150;

  --cta: #5c7e10;
  --cta-from: #75b022;
  --cta-to: #588a1b;
  --cta-foreground: #d2efa9;
  --sale: #4c6b22;
  --sale-foreground: #beee11;
  --review-positive: #66c0f4;
  --live: #e0393e;

  --chart-1: #1a9fff;
  --chart-2: #66c0f4;
  --chart-4: #beee11;
}

/* Ember: blue · black · orange */
[data-theme="ember"] {
  --primary: #1a9fff;
  --primary-from: #06bfff;
  --primary-to: #2d73ff;
  --link: #66c0f4;
  --ring: #66c0f4;
  --secondary: rgb(103 193 245 / 0.2);
  --secondary-foreground: #66c0f4;
  --secondary-from: #417a9b;
  --secondary-to: #66c0f4;
  --nav-tint: 62 103 150;

  --cta: #d9731a;
  --cta-from: #f48c25;
  --cta-to: #c25a0c;
  --cta-foreground: #fff0dd;
  --sale: #6e3a0c;
  --sale-foreground: #ffb347;
  --review-positive: #66c0f4;
  --live: #ff3b42;

  --chart-1: #1a9fff;
  --chart-2: #66c0f4;
  --chart-4: #ffb347;
}

/* Amethyst: violet · black · pink */
[data-theme="amethyst"] {
  --primary: #9b6bff;
  --primary-from: #b98cff;
  --primary-to: #7346e8;
  --link: #c3a6ff;
  --ring: #c3a6ff;
  --secondary: rgb(155 107 255 / 0.2);
  --secondary-foreground: #c3a6ff;
  --secondary-from: #6a4ca8;
  --secondary-to: #b98cff;
  --nav-tint: 104 78 170;

  --cta: #c2357f;
  --cta-from: #e0479e;
  --cta-to: #a8236f;
  --cta-foreground: #ffe0f1;
  --sale: #5e1f47;
  --sale-foreground: #ff7ac6;
  --review-positive: #c3a6ff;
  --live: #ff3b72;

  --chart-1: #9b6bff;
  --chart-2: #c3a6ff;
  --chart-4: #ff7ac6;
}

/* Emerald: green · black · gold */
[data-theme="emerald"] {
  --primary: #2fbf71;
  --primary-from: #4be08e;
  --primary-to: #1c9a55;
  --link: #7be3ac;
  --ring: #7be3ac;
  --secondary: rgb(47 191 113 / 0.2);
  --secondary-foreground: #7be3ac;
  --secondary-from: color-mix(in srgb, #2fbf71 55%, #121214);
  --secondary-to: #7be3ac;
  --nav-tint: 40 110 85;

  --cta: #c99a1c;
  --cta-from: #e8b730;
  --cta-to: #a87a0c;
  --cta-foreground: #fff3cf;
  --sale: #5e4a0c;
  --sale-foreground: #ffd45e;
  --review-positive: #7be3ac;
  --live: #ff3b42;

  --chart-1: #2fbf71;
  --chart-2: #7be3ac;
  --chart-4: #ffd45e;
}

/* Ocean: teal · black · coral */
[data-theme="ocean"] {
  --primary: #12b8c9;
  --primary-from: #38d9e8;
  --primary-to: #0c8ea0;
  --link: #7de3ee;
  --ring: #7de3ee;
  --secondary: rgb(18 184 201 / 0.2);
  --secondary-foreground: #7de3ee;
  --secondary-from: color-mix(in srgb, #12b8c9 55%, #121214);
  --secondary-to: #7de3ee;
  --nav-tint: 40 105 120;

  --cta: #e0583f;
  --cta-from: #ff7358;
  --cta-to: #bf3f28;
  --cta-foreground: #ffe4de;
  --sale: #6e2a1c;
  --sale-foreground: #ff9a85;
  --review-positive: #7de3ee;
  --live: #ff3b42;

  --chart-1: #12b8c9;
  --chart-2: #7de3ee;
  --chart-4: #ff9a85;
}

/* Rose: rose · black · amber */
[data-theme="rose"] {
  --primary: #f0507a;
  --primary-from: #ff7a9c;
  --primary-to: #d02f5c;
  --link: #ff9db7;
  --ring: #ff9db7;
  --secondary: rgb(240 80 122 / 0.2);
  --secondary-foreground: #ff9db7;
  --secondary-from: color-mix(in srgb, #f0507a 55%, #121214);
  --secondary-to: #ff9db7;
  --nav-tint: 150 60 90;

  --cta: #e39a1b;
  --cta-from: #ffb938;
  --cta-to: #bf7a0a;
  --cta-foreground: #fff0d0;
  --sale: #6b4308;
  --sale-foreground: #ffc861;
  --review-positive: #ff9db7;
  --live: #ff3b42;

  --chart-1: #f0507a;
  --chart-2: #ff9db7;
  --chart-4: #ffc861;
}

/* Solar: amber · black · sky */
[data-theme="solar"] {
  --primary: #f5a524;
  --primary-from: #ffc145;
  --primary-to: #d98a0a;
  --link: #ffd27d;
  --ring: #ffd27d;
  --secondary: rgb(245 165 36 / 0.2);
  --secondary-foreground: #ffd27d;
  --secondary-from: color-mix(in srgb, #f5a524 55%, #121214);
  --secondary-to: #ffd27d;
  --nav-tint: 140 100 40;

  --cta: #2a9df4;
  --cta-from: #4db6ff;
  --cta-to: #1a7fd1;
  --cta-foreground: #dff1ff;
  --sale: #17476e;
  --sale-foreground: #7cc8ff;
  --review-positive: #ffd27d;
  --live: #ff3b42;

  --chart-1: #f5a524;
  --chart-2: #ffd27d;
  --chart-4: #7cc8ff;
}

/* 3b. Light mode ------------------------------------------------------------
   <html data-mode="light"> (set by ThemeProvider). Only neutrals change here;
   accent themes keep working because link/ring/secondary text are re-derived
   from --primary so they stay readable on white. */
:root[data-mode="light"] {
  color-scheme: light;

  --header: #ffffff;
  --background: #f4f4f6;
  --surface: #ebebef;
  --card: #ffffff;
  --surface-raised: #e4e4e9;
  --popover: #ffffff;
  --muted: #ececf0;
  --accent: #e6e6ec;
  --accent-foreground: #0e0e11;

  --heading: #0e0e11;
  --foreground: #3a3a42;
  --card-foreground: #3a3a42;
  --popover-foreground: #2a2a30;
  --muted-foreground: #6b6b75;

  --destructive: #d23b3b;

  --success: #16a34a;
  --success-foreground: #ffffff;
  --success-text: #15803d;
  --warning: #d97706;
  --warning-foreground: #ffffff;
  --warning-text: #b45309;
  --info: #2563eb;
  --info-foreground: #ffffff;
  --info-text: #1d4ed8;
  --destructive-text: #b42323;
  --strike: #8a8a94;
  --price-surface: #e2e2e8;
  --review-mixed: #9a7a2a;
  --review-negative: #b5471b;

  --border: rgb(0 0 0 / 0.1);
  --input: #cfcfd6;
  --input-border: #cfcfd6;
  --input-placeholder: #8a8a94;
  --inset-shadow: rgb(0 0 0 / 0.06);
  --tint: rgb(0 0 0 / 0.04);
  --panel-shadow: 0 1px 3px rgb(0 0 0 / 0.1), 0 1px 2px rgb(0 0 0 / 0.06);

  --chart-3: #8a8a94;
  --chart-5: #9a7a2a;

  --sidebar: #ffffff;
  --sidebar-foreground: #3a3a42;
  --sidebar-accent: #e6e6ec;
  --sidebar-accent-foreground: #0e0e11;
  --sidebar-border: rgb(0 0 0 / 0.1);

  --gradient-panel: linear-gradient(180deg, rgb(255 255 255 / 0.9) 0%, rgb(244 244 247 / 0.9) 100%);
  --gradient-hero-info: linear-gradient(135deg, #ffffff 0%, #ececf1 100%);
  --gradient-promo: linear-gradient(90deg, #ececf2 0%, #f8f8fb 100%);
  --page-glow: radial-gradient(ellipse 80% 420px at 50% 0%, rgb(0 0 0 / 0.035), transparent 70%);
}

/* Accent text/surfaces re-derived for light backgrounds. Also applied to nested
   [data-theme] wrappers so a themed subtree inside light mode stays readable. */
:root[data-mode="light"],
[data-mode="light"] [data-theme]:not(.dark) {
  --link: color-mix(in srgb, var(--primary) 72%, black);
  --ring: color-mix(in srgb, var(--primary) 80%, black);
  --secondary: color-mix(in srgb, var(--primary) 14%, transparent);
  --secondary-foreground: color-mix(in srgb, var(--primary) 72%, black);
  --review-positive: color-mix(in srgb, var(--primary) 72%, black);
  --sale: color-mix(in srgb, var(--cta) 16%, white);
  --sale-foreground: color-mix(in srgb, var(--cta) 78%, black);
}

/* 4. Derived (recomputed on every themed element) ------------------------ */
:root,
[data-theme] {
  --sidebar-primary: var(--primary);
  --sidebar-ring: var(--ring);
  --gradient-primary: linear-gradient(90deg, var(--primary-from) 0%, var(--primary-to) 100%);
  --gradient-secondary: linear-gradient(90deg, var(--secondary-from) 0%, var(--secondary-to) 100%);
  --gradient-cta: linear-gradient(180deg, var(--cta-from) 0%, var(--cta-to) 100%);
  --gradient-nav: linear-gradient(90deg, rgb(var(--nav-tint) / 0.55) 10%, rgb(var(--nav-tint) / 0.35) 50%, rgb(var(--nav-tint) / 0.25) 100%);
  --glow: 0 0 12px color-mix(in srgb, var(--primary) 40%, transparent);
  --glow-sm: 0 0 8px color-mix(in srgb, var(--primary) 45%, transparent);
}

/* Utilities --------------------------------------------------------------- */
@utility bg-nav { background-image: var(--gradient-nav); }
@utility bg-panel { background-image: var(--gradient-panel); }
@utility bg-hero-info { background-image: var(--gradient-hero-info); }
@utility bg-primary-gradient { background-image: var(--gradient-primary); }
@utility bg-secondary-gradient { background-image: var(--gradient-secondary); }
@utility bg-cta-gradient { background-image: var(--gradient-cta); }
@utility bg-promo { background-image: var(--gradient-promo); }
@utility text-eyebrow {
  font-size: 0.875rem;
  font-weight: 600;
  letter-spacing: 0.04em;
  text-transform: uppercase;
  color: var(--heading);
}

@layer base {
  * {
    @apply border-border outline-ring/50;
  }
  html {
    @apply font-sans antialiased;
  }
  body {
    @apply min-h-dvh bg-background text-sm text-foreground;
    background-image: var(--page-glow);
    background-repeat: no-repeat;
  }
  h1, h2, h3, h4 {
    @apply font-heading text-heading;
  }
  a {
    @apply transition-colors duration-200 ease-out;
  }
  ::selection {
    background: color-mix(in srgb, var(--primary) 40%, transparent);
    color: #fff;
  }
  @media (prefers-reduced-motion: reduce) {
    *, *::before, *::after {
      animation-duration: 0.01ms !important;
      transition-duration: 0.01ms !important;
    }
  }
}

/* Editor.js (rich-text-editor): bind its popovers and blocks to Malam tokens -------- */
html .ce-popover {
  --color-border: var(--border);
  --color-shadow: rgb(0 0 0 / 0.25);
  --color-background: var(--popover);
  --color-text-primary: var(--popover-foreground);
  --color-text-secondary: var(--muted-foreground);
  --color-background-item-hover: var(--accent);
  --color-background-item-focus: var(--accent);
  --color-border-icon: var(--border);
  --color-text-icon-active: var(--link);
  --color-background-icon-active: color-mix(in srgb, var(--primary) 16%, transparent);
}
html .ce-inline-toolbar,
html .ce-conversion-toolbar {
  background: var(--popover);
  border-color: var(--border);
  color: var(--popover-foreground);
}
html .ce-inline-tool,
html .ce-toolbar__plus,
html .ce-toolbar__settings-btn {
  color: var(--muted-foreground);
}
html .ce-toolbar__plus:hover,
html .ce-toolbar__settings-btn:hover,
html .ce-inline-tool:hover {
  background: var(--accent);
  color: var(--heading);
}
.malam-editor .ce-block__content,
.malam-editor .ce-toolbar__content {
  max-width: none;
}
.malam-editor .ce-block--selected .ce-block__content {
  background: color-mix(in srgb, var(--primary) 16%, transparent);
}
.malam-editor .ce-header {
  color: var(--heading);
  padding: 0.5em 0 0.25em;
}
.malam-editor .ce-paragraph {
  line-height: 1.65;
}
.malam-editor .ce-paragraph[data-placeholder]:empty::before,
.malam-editor [data-placeholder-active]:empty::before {
  color: var(--muted-foreground);
}
.malam-editor .cdx-quote__text {
  min-height: 0;
  background: var(--surface);
  border: 1px solid var(--border);
  box-shadow: none;
}
.malam-editor .cdx-quote__caption {
  color: var(--muted-foreground);
}
.malam-editor .ce-delimiter::before {
  color: var(--muted-foreground);
}
.malam-editor .inline-code {
  background: var(--tint);
  color: var(--link);
  border: 0;
  border-radius: 4px;
  padding: 1px 5px;
  font-family: var(--font-mono);
  font-size: 0.9em;
}
.malam-editor .codex-editor__redactor {
  padding-bottom: 72px !important;
}
/* Tailwind's preflight flattens headings; give Editor.js headings real sizes again. */
.malam-editor h1.ce-header { font-size: 2em; font-weight: 700; }
.malam-editor h2.ce-header { font-size: 1.6em; font-weight: 700; }
.malam-editor h3.ce-header { font-size: 1.35em; font-weight: 650; }
.malam-editor h4.ce-header { font-size: 1.15em; font-weight: 650; }

export { cn } from "cn"

/** Format a price in minor-unit-free numbers, e.g. formatPrice(132839, "IDR"). */
export function formatPrice(value: number, currency = "USD", locale = "en-US") {
  if (value === 0) return "Free"
  return new Intl.NumberFormat(locale, {
    style: "currency",
    currency,
    maximumFractionDigits: currency === "IDR" || currency === "JPY" ? 0 : 2,
  }).format(value)
}
